export function getProviderBySlug(slug: string): ProviderRecord | undefined {
  return PROVIDERS.find((provider) => provider.slug === slug);
}

export function getProvidersForLocation(locationSlug: string): ProviderRecord[] {
  return PROVIDERS.filter((provider) => provider.locationSlugs.includes(locationSlug));
}

export function getNewProviders(): ProviderRecord[] {
  return PROVIDERS.filter((provider) => provider.isNewProvider);
}
